"use client";

import { createClient } from "@neondatabase/auth";

const baseURL = process.env.NEXT_PUBLIC_NEON_AUTH_BASE_URL;

if (!baseURL) {
  throw new Error(
    "Missing NEXT_PUBLIC_NEON_AUTH_BASE_URL. Copy .env.example to .env.local and set your Neon Auth URL."
  );
}

export const auth = createClient({
  baseURL,
});

export async function getSession() {
  const { data, error } = await auth.getSession();
  if (error) throw error;
  return data;
}

export async function signUpEmail(email: string, password: string, name?: string) {
  return auth.signUp.email({
    email,
    password,
    name,
  });
}

export async function signInEmail(email: string, password: string) {
  return auth.signIn.email({
    email,
    password,
  });
}

export async function signOut() {
  return auth.signOut();
}

