  return <main style={{ maxWidth: 720, margin: "40px auto", fontFamily: "Arial, sans-serif" }}><p style={{ color: "crimson" }}>{error}</p></main>;
 }

 if (!session?.user) {
  return (
   <main style={{ maxWidth: 720, margin: "40px auto", fontFamily: "Arial, sans-serif" }}>
    <h1>Dashboard</h1>
    <p>You are not signed in.</p>
    <p><Link href="/login">Go to sign in</Link></p>
   </main>
  );
 }

 return (
